old_string:
// Prefer lobby id when present: join-by-id is what drops you into private / password Steam lobbies.
// Rich-presence "connect" is the fallback for games that publish a connect string instead.
if (lobbyId != 0)
{
    args = new LanJoinArgs
    {
        Kind = LanJoinKind.ConnectLobby,
        ConnectArguments = "+connect_lobby " + lobbyId,
        AppId = appId
    };
    return true;
}

IntPtr connectPtr = _getFriendRichPresence(friends, steamId, "connect");
string connect = PtrToUtf8(connectPtr);
if (!string.IsNullOrWhiteSpace(connect))
{
    args = new LanJoinArgs
    {
        Kind = LanJoinKind.RichPresenceConnect,
        ConnectArguments = connect.Trim(),
        AppId = appId
    };
    return true;
}

// Friend is on the network but has no lobby/connect yet — caller keeps polling.
return false;

